    // commitIfEditing in onPooled (the focus-loss ordering does not hold
    // on recycle, so the flush is explicit).
    function resetDisplay() {
        commitFrame = -1
        commitModel = -1
        commitAxis = -1
        edited = false
        text = Qt.binding(() => storedValue.toFixed(3))
    }
}

